using System;

public class Person {
    public virtual string Name { get; set; }
}

public class Student : Person { }

public class C {
    public void M(Person p) {
        switch (p) {
            case { Name: "Bill" }:
                Console.WriteLine("Hey Bill!");
            break;
            case Student { Name: var name }:
                Console.WriteLine($"Hello student { name}!");
            break;
        }
    }
}
